package io.github.ningpp.compat;

import java.lang.reflect.Array;

/** Replacement for System.Runtime.InteropServices.MemoryMarshal (generated by CSharpToJava converter). */
public class MemoryMarshal {
    /**
     * Mirrors C# MemoryMarshal.AsBytes — reinterprets numeric elements as bytes
     * (4 bytes per element) and character elements as UTF-16 little-endian bytes
     * (2 bytes per element), matching ReadOnlySpan&lt;char&gt; layout on .NET.
     */
    @SuppressWarnings("unchecked")
    public static ReadOnlySpan<Integer> asBytes(ReadOnlySpan span) {
        int len = span.length();
        if (len > 0 && span.get(0) instanceof Character) {
            Integer[] bytes = new Integer[len * 2];
            for (int i = 0; i < len; i++) {
                int cp = (Character) span.get(i);
                bytes[i * 2] = cp & 0xFF;
                bytes[i * 2 + 1] = (cp >>> 8) & 0xFF;
            }
            return new ReadOnlySpan<>(bytes);
        }
        Integer[] bytes = new Integer[len * 4];
        for (int i = 0; i < len; i++) {
            int cp = ((Number) span.get(i)).intValue();
            bytes[i * 4] = (cp >>> 24) & 0xFF;
            bytes[i * 4 + 1] = (cp >>> 16) & 0xFF;
            bytes[i * 4 + 2] = (cp >>> 8) & 0xFF;
            bytes[i * 4 + 3] = cp & 0xFF;
        }
        return new ReadOnlySpan<>(bytes);
    }

    /** Overload for the converter's mutable Span re-wrapping of char[].AsSpan. */
    public static ReadOnlySpan<Integer> asBytes(Span span) {
        return asBytes(span.asReadOnlySpan());
    }

    /** Mirrors C# MemoryMarshal.Read&lt;int&gt;(ReadOnlySpan&lt;byte&gt;) — little-endian 4-byte read. */
    public static int read(ReadOnlySpan<Integer> span) {
        int value = 0;
        int count = Math.min(4, span.length());
        for (int i = 0; i < count; i++) {
            value |= (span.get(i) & 0xFF) << (i * 8);
        }
        return value;
    }

    /** Mirrors C# MemoryMarshal.Read&lt;long&gt;(ReadOnlySpan&lt;byte&gt;) — little-endian 8-byte read. */
    public static long readLong(ReadOnlySpan<Integer> span) {
        long value = 0;
        int count = Math.min(8, span.length());
        for (int i = 0; i < count; i++) {
            value |= (long) (span.get(i) & 0xFF) << (i * 8);
        }
        return value;
    }

    /**
     * Mirrors C# MemoryMarshal.GetReference&lt;T&gt;(Span&lt;T&gt;): Java has no ref
     * returns, so this yields the first element by value (call sites read it).
     */
    public static <T> T getReference(Span<T> span) {
        return span.get(0);
    }

    /**
     * Mirrors C# MemoryMarshal.GetReference&lt;T&gt;(ReadOnlySpan&lt;T&gt;): Java has no ref
     * returns, so this yields the first element by value (call sites read it).
     * Returns {@code null} for an empty span (C# returns a ref to the backing buffer,
     * which is unsafe to dereference; returning null is the safe Java equivalent).
     */
    public static <T> T getReference(ReadOnlySpan<T> span) {
        return span.length() > 0 ? span.get(0) : null;
    }

    /**
     * Mirrors C# MemoryMarshal.CreateSpan&lt;char&gt;(ref char reference, int length):
     * the converter lowers the ref char argument into a CharHolder, so unwrap the
     * holder's value to seed a char-typed span (CharConverter.Write/WriteWithQuotes
     * call Utf8JsonWriter.writeStringValue/writePropertyName with it).
     */
    public static Span<Character> createSpan(CharHolder first, int length) {
        Character[] arr = new Character[length];
        if (length > 0 && first != null) {
            arr[0] = first.value;
        }
        return new Span<>(arr);
    }

    /**
     * Mirrors C# MemoryMarshal.CreateSpan&lt;T&gt;(ref T reference, int length):
     * creates a Span of {@code length} elements seeded from the first field of a
     * generated struct/class (e.g. FourStackStrings.Item1). Subsequent fields are
     * read via reflection so stackalloc-like multi-field structs work.
     */
    @SuppressWarnings("unchecked")
    public static <T> Span<T> createSpan(T first, int length) {
        Object[] arr = new Object[length];
        if (length > 0) {
            arr[0] = first;
        }
        if (length > 1 && first != null) {
            java.lang.reflect.Field[] fields = first.getClass().getFields();
            // arr[0] already holds Item1 (the `first` argument); arr[i] maps to fields[i]
            // (Item2..ItemN) since getFields() returns the public fields in declaration order.
            for (int i = 1; i < length && i < fields.length; i++) {
                try {
                    arr[i] = fields[i].get(first);
                } catch (IllegalAccessException e) {
                    arr[i] = null;
                }
            }
        }
        return new Span<>((T[]) arr);
    }

    /** Mirrors MemoryMarshal.Read&lt;T&gt;(ReadOnlySpan&lt;byte&gt;) for struct targets — default instance. */
    public static <T> T read(ReadOnlySpan<Integer> span, Class<T> type) {
        try {
            var ctor = type.getDeclaredConstructor();
            ctor.setAccessible(true);
            return ctor.newInstance();
        } catch (ReflectiveOperationException e) {
            return null;
        }
    }

    /** Mirrors MemoryMarshal.Cast&lt;TFrom, TTo&gt;(Span&lt;TFrom&gt;) — element reinterpretation is a no-op. */
    public static Span<Integer> cast(Span<Integer> span) {
        return span;
    }

    /** Mirrors MemoryMarshal.Write&lt;T&gt;(Span&lt;byte&gt;, ref T) — writes the value as little-endian bytes. */
    public static <T> void write(Span<Integer> span, ObjectHolder<T> value) {
        writeValue(span, value.value);
    }

    /** Mirrors MemoryMarshal.Write&lt;int&gt;(Span&lt;byte&gt;, ref int). */
    public static void write(Span<Integer> span, IntHolder value) {
        writeValue(span, value.value);
    }

    /** Mirrors MemoryMarshal.Write&lt;long&gt;(Span&lt;byte&gt;, ref long). */
    public static void write(Span<Integer> span, LongHolder value) {
        writeValue(span, value.value);
    }

    private static void writeValue(Span<Integer> span, Object value) {
        if (value instanceof Number n) {
            long lv = n.longValue();
            for (int i = 0; i < span.length() && i < 8; i++) {
                span.set(i, (int) ((lv >>> (i * 8)) & 0xFF));
            }
            return;
        }
        for (int i = 0; i < span.length(); i++) {
            span.set(i, 0);
        }
    }
}
